const std::array<NormalizedTemplate, 10> &normalizedFontTemplates() {
  static const std::array<NormalizedTemplate, 10> tables = [] {
    std::array<NormalizedTemplate, 10> out{};
    for (int d = 0; d < 10; ++d) {
      double sum = 0.0;
      for (int i = 0; i < kDigitW * kDigitH; ++i)
        sum += kFontDigitTemplates[d][i];
      const double mean = sum / double(kDigitW * kDigitH);
      double sq = 0.0;
      for (int i = 0; i < kDigitW * kDigitH; ++i) {
        const double v = double(kFontDigitTemplates[d][i]) - mean;
        out[size_t(d)].centered[size_t(i)] = float(v);
        sq += v * v;
      }
      out[size_t(d)].norm = std::sqrt(sq);
    }
    return out;
  }();
  return tables;
}
double matchDigitNcc(const std::array<float, kPatchW * kPatchH> &patch,
                     const NormalizedTemplate &tmpl) {
  if (tmpl.norm < 1e-6)
    return 0.0;
  double best = 0.0;
  for (int dy = -kSearchRadius; dy <= kSearchRadius; ++dy) {
    for (int dx = -kSearchRadius; dx <= kSearchRadius; ++dx) {
      const int oy = kSearchRadius + dy;
      const int ox = kSearchRadius + dx;
      double sum = 0.0;
      for (int y = 0; y < kDigitH; ++y) {
        const float *row = patch.data() + size_t(oy + y) * kPatchW + ox;
        for (int x = 0; x < kDigitW; ++x)
          sum += row[x];
      }
      const double mean = sum / double(kDigitW * kDigitH);
      double sq = 0.0;
      double dot = 0.0;
      for (int y = 0; y < kDigitH; ++y) {
        const float *row = patch.data() + size_t(oy + y) * kPatchW + ox;
        const float *trow = tmpl.centered.data() + size_t(y) * kDigitW;
        for (int x = 0; x < kDigitW; ++x) {
          const double diff = row[x] - mean;
          sq += diff * diff;
          dot += diff * trow[x];
        }
      }
      if (sq > 100.0) {
        const double corr = std::abs(dot / (std::sqrt(sq) * tmpl.norm));
        best = std::max(best, corr);
      }
    }
  }
  return best;
}

struct SlotMatch {
  int digit{-1};
  double confidence{0.0};
  double margin{0.0};
};

SlotMatch readDigitSlot(const QImage &argb32, int row, int slot) {
  const int rowY = int(std::lround(112.0 + 78.0 * row));
  const int x0 = 1800 - 26 * slot;
  const int y0 = rowY - 14;
  if (x0 < 0 || y0 < 0 || x0 + kPatchW > argb32.width() || y0 + kPatchH > argb32.height())
    return {};

  std::array<float, kPatchW * kPatchH> patch{};
  for (int y = 0; y < kPatchH; ++y) {
    const uint8_t *bgra = argb32.constScanLine(y0 + y) + x0 * 4;
    for (int x = 0; x < kPatchW; ++x) {
      const float b = bgra[x * 4 + 0];
      const float g = bgra[x * 4 + 1];
      const float r = bgra[x * 4 + 2];
      patch[size_t(y * kPatchW + x)] = 0.114f * b + 0.587f * g + 0.299f * r;
    }
  }

  const auto &tmpls = normalizedTemplates();
  const auto &fontTmpls = normalizedFontTemplates();
  double best = 0.0, second = 0.0;
  int bestDigit = -1;
  for (int d = 0; d < 10; ++d) {
    const double score = std::max(matchDigitNcc(patch, tmpls[size_t(d)]), matchDigitNcc(patch, fontTmpls[size_t(d)]));
    if (score > best) {
      second = best;
      best = score;
      bestDigit = d;
    } else if (score > second) {
      second = score;
    }
  }
  return {bestDigit, best, best - second};
}

