StandingsScoreRead readCumulativeScores(const QImage &frame1920) {
  StandingsScoreRead out;
  if (frame1920.isNull())
    return out;
  const QImage argb = (frame1920.size() == QSize(1920, 1080)
                           ? frame1920
                           : frame1920.scaled(1920, 1080, Qt::IgnoreAspectRatio,
                                              Qt::SmoothTransformation))
                          .convertToFormat(QImage::Format_ARGB32);

  constexpr double kMinScore = 0.72;
  constexpr double kMinMargin = 0.05;

  bool nonIncreasing = true;
  int previousPoints = 1000000;
  for (int row = 0; row < 12; ++row) {
    const SlotMatch units = readDigitSlot(argb, row, 0);
    if (units.digit < 0 || units.confidence < kMinScore || units.margin < kMinMargin)
      continue;

    int value = units.digit;
    double minConf = units.confidence;
    double minMargin = units.margin;

    const SlotMatch tens = readDigitSlot(argb, row, 1);
    if (tens.digit >= 0 && tens.confidence >= kMinScore && tens.margin >= kMinMargin) {
      const SlotMatch hundreds = readDigitSlot(argb, row, 2);
      if (hundreds.digit >= 1 && hundreds.confidence >= kMinScore &&
          hundreds.margin >= kMinMargin) {
        value = hundreds.digit * 100 + tens.digit * 10 + units.digit;
        minConf = std::min(minConf, std::min(tens.confidence, hundreds.confidence));
        minMargin = std::min(minMargin, std::min(tens.margin, hundreds.margin));
      } else if (tens.digit >= 1) {
        value = tens.digit * 10 + units.digit;
        minConf = std::min(minConf, tens.confidence);
        minMargin = std::min(minMargin, tens.margin);
      }
    }

    out.rows[size_t(row)] = {value, minConf, minMargin};
    out.totalPoints += value;
    ++out.validRows;
    if (value > previousPoints)
      nonIncreasing = false;
    previousPoints = value;
  }
  out.nonIncreasing = (out.validRows == 12) && nonIncreasing;
  return out;
}

